import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Протокол Mux.Cool","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/protocols/muxcool.md","filePath":"ru/development/protocols/muxcool.md","lastUpdated":1744252752000}`),a={name:`ru/development/protocols/muxcool.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="протокол-mux-cool" tabindex="-1">Протокол Mux.Cool <a class="header-anchor" href="#протокол-mux-cool" aria-label="Permalink to “Протокол Mux.Cool”">​</a></h1><p>Протокол Mux.Cool - это мультиплексирующий транспортный протокол, используемый для передачи нескольких независимых потоков данных по одному установленному потоку данных.</p><h2 id="версия" tabindex="-1">Версия <a class="header-anchor" href="#версия" aria-label="Permalink to “Версия”">​</a></h2><p>Текущая версия - 1 Beta.</p><h2 id="зависимости" tabindex="-1">Зависимости <a class="header-anchor" href="#зависимости" aria-label="Permalink to “Зависимости”">​</a></h2><h3 id="базовыи-протокол" tabindex="-1">Базовый протокол <a class="header-anchor" href="#базовыи-протокол" aria-label="Permalink to “Базовый протокол”">​</a></h3><p>Mux.Cool должен работать поверх установленного надежного потока данных.</p><h2 id="процесс-коммуникации" tabindex="-1">Процесс коммуникации <a class="header-anchor" href="#процесс-коммуникации" aria-label="Permalink to “Процесс коммуникации”">​</a></h2><p>Одно соединение Mux.Cool может передавать несколько подсоединений, каждое из которых имеет свой собственный идентификатор и состояние. Процесс передачи состоит из кадров (Frame), каждый из которых используется для передачи данных определенного подсоединения.</p><h3 id="поведение-клиента" tabindex="-1">Поведение клиента <a class="header-anchor" href="#поведение-клиента" aria-label="Permalink to “Поведение клиента”">​</a></h3><p>Когда требуется соединение и нет доступного существующего соединения, клиент инициирует новое соединение с сервером, которое далее называется &quot;главным соединением&quot;.</p><ol><li>Одно главное соединение может использоваться для отправки нескольких подсоединений. Клиент может самостоятельно определять количество подсоединений, которое может нести главное соединение.</li><li>Для нового подсоединения клиент должен отправить состояние <code>New</code>, чтобы уведомить сервер о создании подсоединения, а затем использовать состояние <code>Keep</code> для передачи данных.</li><li>Когда подсоединение завершается, клиент отправляет состояние <code>End</code>, чтобы уведомить сервер о закрытии подсоединения.</li><li>Клиент может самостоятельно решать, когда закрыть главное соединение, но должен убедиться, что сервер также поддерживает соединение.</li><li>Клиент может использовать состояние KeepAlive, чтобы предотвратить закрытие главного соединения сервером.</li></ol><h3 id="поведение-сервера" tabindex="-1">Поведение сервера <a class="header-anchor" href="#поведение-сервера" aria-label="Permalink to “Поведение сервера”">​</a></h3><p>Когда сервер получает новое подсоединение, он должен обрабатывать его как обычное соединение.</p><ol><li>При получении состояния <code>End</code> сервер может закрыть исходящее соединение с целевым адресом.</li><li>В ответе сервера для передачи данных подсоединения должен использоваться тот же идентификатор, что и в запросе.</li><li>Сервер не может использовать состояние <code>New</code>.</li><li>Сервер может использовать состояние KeepAlive, чтобы предотвратить закрытие главного соединения клиентом.</li></ol><h2 id="формат-передачи" tabindex="-1">Формат передачи <a class="header-anchor" href="#формат-передачи" aria-label="Permalink to “Формат передачи”">​</a></h2><p>Mux.Cool использует симметричный формат передачи, то есть клиент и сервер отправляют и получают данные в одинаковом формате.</p><h3 id="формат-кадра" tabindex="-1">Формат кадра <a class="header-anchor" href="#формат-кадра" aria-label="Permalink to “Формат кадра”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>L байт</th><th>X байт</th></tr></thead><tbody><tr><td>Длина метаданных L</td><td>Метаданные</td><td>Дополнительные данные</td></tr></tbody></table><h3 id="метаданные" tabindex="-1">Метаданные <a class="header-anchor" href="#метаданные" aria-label="Permalink to “Метаданные”">​</a></h3><p>Существует несколько типов метаданных. Все типы метаданных содержат поля ID и Opt, которые означают следующее:</p><ul><li>ID: уникальный идентификатор подсоединения <ul><li>Для обычных подсоединений Mux ID начинается с 1 и увеличивается</li><li>Для <a href="https://github.com/XTLS/Xray-core/blob/main/common/xudp/xudp.go" target="_blank" rel="noreferrer">Single XUDP</a>, реализованного в Xray, ID всегда равен 0</li></ul></li><li>Opt: <ul><li>D(0x01): есть дополнительные данные</li></ul></li></ul><p>Если опция Opt(D) включена, формат дополнительных данных следующий:</p><table tabindex="0"><thead><tr><th>2 байта</th><th>X-2 байта</th></tr></thead><tbody><tr><td>Длина X-2</td><td>Данные</td></tr></tbody></table><h3 id="создание-нового-подсоединения-new" tabindex="-1">Создание нового подсоединения (New) <a class="header-anchor" href="#создание-нового-подсоединения-new" aria-label="Permalink to “Создание нового подсоединения (New)”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th><th>1 байт</th><th>2 байта</th><th>1 байт</th><th>A байт</th><th>8 байт</th></tr></thead><tbody><tr><td>ID</td><td>0x01</td><td>Опция Opt</td><td>Тип сети N</td><td>Порт</td><td>Тип адреса T</td><td>Адрес A</td><td>Global ID (XUDP)</td></tr></tbody></table><p>Где:</p><ul><li>Тип сети N: <ul><li>0x01: TCP, указывает, что трафик текущего подсоединения должен быть отправлен на целевой адрес по TCP.</li><li>0x02: UDP, указывает, что трафик текущего подсоединения должен быть отправлен на целевой адрес по UDP.</li></ul></li><li>Тип адреса T: <ul><li>0x01: IPv4</li><li>0x02: доменное имя</li><li>0x03: IPv6</li></ul></li><li>Адрес A: <ul><li>Если T = 0x01, A - это 4-байтовый адрес IPv4;</li><li>Если T = 0x02, A - это 1 байт длины (L) + L байт доменного имени;</li><li>Если T = 0x03, A - это 16-байтовый адрес IPv6;</li></ul></li><li>Global ID (XUDP): <ul><li>Клиент вычисляет глобально уникальный идентификатор исходного кортежа UDP, который сервер использует, чтобы гарантировать, что при переподключении XUDP будет использоваться тот же порт для связи с целевым адресом.</li></ul></li></ul><p>При создании нового подсоединения, если Opt(D) включена, данные, переносимые этим кадром, должны быть отправлены на целевой хост.</p><h3 id="поддержание-подсоединения-keep" tabindex="-1">Поддержание подсоединения (Keep) <a class="header-anchor" href="#поддержание-подсоединения-keep" aria-label="Permalink to “Поддержание подсоединения (Keep)”">​</a></h3><p>TCP</p><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th></tr></thead><tbody><tr><td>ID</td><td>0x02</td><td>Опция Opt</td></tr></tbody></table><p>UDP</p><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th><th>1 байт</th><th>2 байта</th><th>1 байт</th><th>A байт</th></tr></thead><tbody><tr><td>ID</td><td>0x02</td><td>Опция Opt</td><td>Тип сети N</td><td>Порт</td><td>Тип адреса T</td><td>Адрес A</td></tr></tbody></table><p>При поддержании подсоединения, если Opt(D) включена, данные, переносимые этим кадром, должны быть отправлены на целевой хост. XUDP добавляет адрес UDP после Opt(D) в том же формате, что и при создании нового подсоединения, но без Global ID.</p><h3 id="закрытие-подсоединения-end" tabindex="-1">Закрытие подсоединения (End) <a class="header-anchor" href="#закрытие-подсоединения-end" aria-label="Permalink to “Закрытие подсоединения (End)”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th></tr></thead><tbody><tr><td>ID</td><td>0x03</td><td>Опция Opt</td></tr></tbody></table><p>При поддержании подсоединения, если Opt(D) включена, данные, переносимые этим кадром, должны быть отправлены на целевой хост.</p><h3 id="поддержание-соединения-keepalive" tabindex="-1">Поддержание соединения (KeepAlive) <a class="header-anchor" href="#поддержание-соединения-keepalive" aria-label="Permalink to “Поддержание соединения (KeepAlive)”">​</a></h3><table tabindex="0"><thead><tr><th>2 байта</th><th>1 байт</th><th>1 байт</th></tr></thead><tbody><tr><td>ID</td><td>0x04</td><td>Опция Opt</td></tr></tbody></table><p>При поддержании соединения:</p><ul><li>Если Opt(D) включена, данные, переносимые этим кадром, должны быть отброшены.</li><li>ID может быть случайным значением.</li></ul><h2 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to “Применение”">​</a></h2><p>Протокол Mux.Cool не зависит от базового протокола и теоретически может использовать любое надежное потоковое соединение для передачи данных протокола Mux.Cool.</p><p>В протоколах, ориентированных на целевой адрес, таких как Shadowsocks и VMess, при установлении соединения должен быть указан целевой адрес. Для обеспечения совместимости протокол Mux.Cool определяет адрес &quot;v1.mux.cool&quot;. То есть, если целевой адрес главного соединения совпадает с этим адресом, пересылка осуществляется в режиме Mux.Cool, в противном случае пересылка осуществляется традиционным способом. (Примечание: это внутренняя метка программы, VMess и VLESS не отправляют адрес &quot;v1.mux.cool&quot; в пакетах данных).</p>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};